/*
 * Good Eye / עין טובה — service worker: lets the standalone app open and work without internet.
 * Generated by tools/gen_sw.py — edit tools/sw.template.js, not sw.js.
 *  - App files: pre-cached on install; served network-first (so updates arrive), cache when offline.
 *  - Libraries, fonts and the face model from CDNs: cached the first time they are used.
 *  - Never caches sync requests (/api/).
 */
var VERSION = 'f28038849c';
var APP_CACHE = 'good-eye-app-' + VERSION;
var LIB_CACHE = 'good-eye-libs-v1';
var FILES = [
  './',
  'index.html',
  'manifest.webmanifest',
  'icon.svg',
  'css/style.css',
  'js/content/sentences.js',
  'js/content/stimuli.js',
  'js/core/ai.js',
  'js/core/cloud.js',
  'js/core/device.js',
  'js/core/history.js',
  'js/core/i18n-en.js',
  'js/core/i18n.js',
  'js/core/loader.js',
  'js/core/profiles.js',
  'js/core/settings.js',
  'js/core/storage.js',
  'js/core/sync.js',
  'js/engine/deformation.js',
  'js/engine/imageproc.js',
  'js/instruments/grid.js',
  'js/main.js',
  'js/render/lens.js',
  'js/screens/calibrate.js',
  'js/screens/fieldtest.js',
  'js/screens/history.js',
  'js/screens/home.js',
  'js/screens/lab.js',
  'js/screens/learn.js',
  'js/screens/reader.js',
  'js/screens/readtest.js',
  'js/screens/tools.js',
  'js/ui/common.js',
  'js/ui/drawer.js',
  'js/ui/eyepanel.js',
  'js/vision/eyes.js'
];
var LIB_HOSTS = ['cdnjs.cloudflare.com', 'cdn.jsdelivr.net', 'fonts.googleapis.com', 'fonts.gstatic.com', 'storage.googleapis.com'];

self.addEventListener('install', function (e) {
  e.waitUntil(caches.open(APP_CACHE).then(function (c) { return c.addAll(FILES); }).then(function () { return self.skipWaiting(); }));
});

self.addEventListener('activate', function (e) {
  e.waitUntil(caches.keys().then(function (keys) {
    return Promise.all(keys.filter(function (k) { return k.indexOf('good-eye-app-') === 0 && k !== APP_CACHE; }).map(function (k) { return caches.delete(k); }));
  }).then(function () { return self.clients.claim(); }));
});

self.addEventListener('fetch', function (e) {
  var req = e.request;
  if (req.method !== 'GET') return;
  var url = new URL(req.url);
  if (url.pathname.indexOf('/api/') === 0) return;               // sync: always live
  if (url.origin === self.location.origin) {
    // network first, fall back to the cached copy when offline
    e.respondWith(fetch(req).then(function (res) {
      if (res.ok) { var copy = res.clone(); caches.open(APP_CACHE).then(function (c) { c.put(req, copy); }); }
      return res;
    }).catch(function () {
      return caches.match(req, { ignoreSearch: true }).then(function (hit) { return hit || caches.match('index.html'); });
    }));
    return;
  }
  if (LIB_HOSTS.indexOf(url.hostname) >= 0) {
    // versioned libraries and fonts: cache first
    e.respondWith(caches.open(LIB_CACHE).then(function (c) {
      return c.match(req).then(function (hit) {
        return hit || fetch(req).then(function (res) { if (res.ok || res.type === 'opaque') c.put(req, res.clone()); return res; });
      });
    }));
  }
});
